/* ============================ 2. ISLAND MAP =============================== */
/** Pure data/logic: island mask, path network, tile classification and cliff layout (no Phaser calls). */
class IslandMap {
  constructor() {
    this.raw = MASK.split('|').map(r => [...r.matchAll(/([.gc])(\d+)/g)].map(m => m[1].repeat(+m[2])).join('').replace(/c/g, '.'));
    this.segs = this.buildPaths();
    this.types = new Uint8Array(MW * MH);
    for (let j = 0; j < MH; j++) for (let i = 0; i < MW; i++) {
      if (!this.plat(i, j)) continue;
      let rim = false; for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) if (!this.plat(i + a, j + b)) rim = true;   // 8-neighbour rim = gap-free blocker
      this.types[j * MW + i] = rim ? RIM : this.pathDist(i + .5, j + .5) < 1.1 ? PATH : GRASS;
    }
    this.cliffs = this.genCliffs();
  }
  ch(i, j) { return (i < 0 || j < 0 || i >= MW || j >= MH) ? '.' : this.raw[j][i]; }
  plat(i, j) { return this.ch(i, j) === 'g'; }
  type(i, j) { return (i < 0 || j < 0 || i >= MW || j >= MH) ? 0 : this.types[j * MW + i]; }

  /** Two circular paths (outer ring + fountain ring), 5 spokes, and a door branch per building. */
  buildPaths() {
    const circ = (r, n) => Array.from({ length: n }, (_, i) => { const a = i / n * 2 * Math.PI; return [CX + r * Math.cos(a), CY + r * Math.sin(a)]; });
    const loop = p => p.map((q, i) => [q, p[(i + 1) % p.length]]);
    const ringPt = ([x, y]) => { const d = Math.hypot(x - CX, y - CY); return [CX + (x - CX) / d * RO, CY + (y - CY) / d * RO]; };
    const segs = [...loop(circ(RO, 90)), ...loop(circ(RI, 36))];
    for (const b of BUILDINGS) {
      const pts = [[b.ax, b.ay + .3]]; if (b.gx != null) pts.push([b.ax, b.ay + b.gy], [b.ax + b.gx, b.ay + b.gy]);
      const P = ringPt(pts[pts.length - 1]); pts.push(P);
      b.P = P; b.Q = [CX + (P[0] - CX) / RO * RI, CY + (P[1] - CY) / RO * RI];      // P: spoke meets outer ring, Q: spoke meets inner ring
      for (let i = 1; i < pts.length; i++) segs.push([pts[i - 1], pts[i]]);
      segs.push([b.Q, P]);
    }
    return segs;
  }
  /** Nearest point on any path: returns [distance, dx, dy] (tile units). */
  nearestPath(x, y) {
    let best = 1e9, v = [0, 0];
    for (const [[x1, y1], [x2, y2]] of this.segs) {
      const dx = x2 - x1, dy = y2 - y1; let t = ((x - x1) * dx + (y - y1) * dy) / (dx * dx + dy * dy); t = Math.max(0, Math.min(1, t));
      const qx = x1 + t * dx - x, qy = y1 + t * dy - y, d = Math.hypot(qx, qy); if (d < best) { best = d; v = [qx, qy]; }
    }
    return [best, v[0], v[1]];
  }
  pathDist(x, y) { return this.nearestPath(x, y)[0]; }

  /** Cliff layout: walkable top edge -> wall face -> wall-into-water base; end caps on every run end; side pieces on east/west coasts. */
  genCliffs() {
    const edge = (i, j) => this.plat(i, j) && !this.plat(i, j + 1);
    const m = { top: [], face: [], base: [], side: [] };
    for (let j = 0; j < MH + 4; j++) for (const k of Object.keys(m)) m[k][j] = Array(MW).fill(null);
    for (let j = 0; j < MH; j++) for (let i = 0; i < MW; i++) {
      if (!this.plat(i, j)) continue; const h = hs(i, j);
      if (edge(i, j)) {
        const l = !edge(i - 1, j), r = !edge(i + 1, j), e = l && !r ? 'L' : r && !l ? 'R' : '';
        m.top[j][i] = 'T' + (e || h % 4);
        if (e) m.face[j + 1][i] = 'C' + e; else { m.face[j + 1][i] = 'F' + (h % 3); m.base[j + 2][i] = 'B' + (h % 2); }
      } else if (!this.plat(i + 1, j)) m.side[j][i] = 'R';
      else if (!this.plat(i - 1, j)) m.side[j][i] = 'L';
    }
    return m;
  }
}

/* ============================== 3. NAV GRID =============================== */
/** Tile walkability + A* so taps/clicks route around trees, rocks, lamps and buildings and can never target water or cliffs. */
class NavGrid {
  constructor(island, solidRects) {
    this.ok = new Uint8Array(MW * MH);
    for (let j = 0; j < MH; j++) for (let i = 0; i < MW; i++) {
      const t = island.type(i, j); if (t !== GRASS && t !== PATH) continue;                 // water, cliff, rim: never walkable
      const cx = (i + .5) * T, cy = (j + .5) * T;
      if (solidRects.some(r => cx > r[0] - 4 && cx < r[0] + r[2] + 4 && cy > r[1] - 4 && cy < r[1] + r[3] + 4)) continue;
      this.ok[j * MW + i] = 1;
    }
  }
  walkable(i, j) { return i >= 0 && j >= 0 && i < MW && j < MH && this.ok[j * MW + i] === 1; }
  /** Nearest walkable tile to a world point (clamps invalid targets onto the island), or null. */
  nearest(px, py, maxR = 8) {
    const ci = Math.floor(px / T), cj = Math.floor(py / T); let best = null, bd = 1e9;
    for (let dj = -maxR; dj <= maxR; dj++) for (let di = -maxR; di <= maxR; di++) {
      if (!this.walkable(ci + di, cj + dj)) continue;
      const d = Math.hypot((ci + di + .5) * T - px, (cj + dj + .5) * T - py); if (d < bd) { bd = d; best = [ci + di, cj + dj]; }
    }
    return best;
  }
  clear(x1, y1, x2, y2) {                                                                      // straight line stays on walkable tiles?
    const n = Math.ceil(Math.hypot(x2 - x1, y2 - y1) / 10);
    for (let k = 0; k <= n; k++) { const t = k / n; if (!this.walkable(Math.floor((x1 + (x2 - x1) * t) / T), Math.floor((y1 + (y2 - y1) * t) / T))) return false; }
    return true;
  }
  /** A* (8-way, no corner cutting). Returns world-space waypoints or null if the goal is unreachable. */
  path(sx, sy, gx, gy) {
    const s = this.nearest(sx, sy, 3), g = this.nearest(gx, gy); if (!s || !g) return null;
    const idx = (i, j) => j * MW + i, G = new Float32Array(MW * MH).fill(1e9), prev = new Int32Array(MW * MH).fill(-1), done = new Uint8Array(MW * MH);
    const h = (i, j) => { const dx = Math.abs(i - g[0]), dy = Math.abs(j - g[1]); return (dx + dy) + (Math.SQRT2 - 2) * Math.min(dx, dy); };
    const heap = [[h(...s), s[0], s[1]]]; G[idx(...s)] = 0;
    const push = n => { heap.push(n); let k = heap.length - 1; while (k > 0) { const p = (k - 1) >> 1; if (heap[p][0] <= heap[k][0]) break; [heap[p], heap[k]] = [heap[k], heap[p]]; k = p; } };
    const pop = () => { const top = heap[0], last = heap.pop(); if (heap.length) { heap[0] = last; let k = 0; for (;;) { let l = 2 * k + 1, r = l + 1, m = k; if (l < heap.length && heap[l][0] < heap[m][0]) m = l; if (r < heap.length && heap[r][0] < heap[m][0]) m = r; if (m === k) break; [heap[m], heap[k]] = [heap[k], heap[m]]; k = m; } } return top; };
    while (heap.length) {
      const [, i, j] = pop(), id = idx(i, j); if (done[id]) continue; done[id] = 1;
      if (i === g[0] && j === g[1]) break;
      for (let dj = -1; dj <= 1; dj++) for (let di = -1; di <= 1; di++) {
        if (!di && !dj) continue; const ni = i + di, nj = j + dj; if (!this.walkable(ni, nj)) continue;
        if (di && dj && (!this.walkable(i + di, j) || !this.walkable(i, j + dj))) continue;
        const ng = G[id] + (di && dj ? Math.SQRT2 : 1), nid = idx(ni, nj);
        if (ng < G[nid]) { G[nid] = ng; prev[nid] = id; push([ng + h(ni, nj), ni, nj]); }
      }
    }
    if (!done[idx(...g)]) return null;
    const pts = []; for (let id = idx(...g); id !== -1; id = prev[id]) pts.push({ x: ((id % MW) + .5) * T, y: (Math.floor(id / MW) + .5) * T });
    pts.reverse();
    const gt = Math.floor(gx / T) === g[0] && Math.floor(gy / T) === g[1];                   // exact tap point if its own tile is walkable
    if (gt) pts[pts.length - 1] = { x: gx, y: gy };
    const out = []; let a = { x: sx, y: sy }, k = 0;                                          // string-pulling: skip waypoints with a clear straight line
    while (k < pts.length) { let far = k; for (let m = pts.length - 1; m > k; m--) if (this.clear(a.x, a.y, pts[m].x, pts[m].y)) { far = m; break; } out.push(pts[far]); a = pts[far]; k = far + 1; }
    return out;
  }
}

/* ============================ 4. AUDIO SYSTEM ============================= */
/** Web Audio: procedural BGM + SFX (no audio files needed). Independent volume + mute for Music and SFX, saved in localStorage. */
class AudioSystem {
  constructor() {
    this.ctx = null; this.timer = null;
    this.st = { music: { vol: 0.5, mute: false }, sfx: { vol: 0.7, mute: false } };
    try { Object.assign(this.st.music, JSON.parse(localStorage.getItem('island.music'))); Object.assign(this.st.sfx, JSON.parse(localStorage.getItem('island.sfx'))); } catch (e) { /* ignore */ }
    for (const ch of ['music', 'sfx']) {
      const slider = document.getElementById('vol-' + ch), btn = document.getElementById('mute-' + ch);
      if (!slider || !btn) continue;
      slider.value = Math.round(this.st[ch].vol * 100);
      slider.addEventListener('input', () => { this.st[ch].vol = slider.value / 100; if (this.st[ch].vol > 0) this.st[ch].mute = false; this.refresh(); if (ch === 'sfx') this.sfx('click'); });
      btn.addEventListener('click', () => { this.st[ch].mute = !this.st[ch].mute; this.refresh(); if (ch === 'sfx') this.sfx('click'); });
    }
    ['pointerdown', 'keydown', 'touchend'].forEach(ev => addEventListener(ev, () => this.unlock(), { passive: true }));   // browsers need a gesture first
    this.refresh();
  }
  unlock() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext; if (!AC) return;
      const c = this.ctx = new AC();
      this.musicGain = c.createGain(); this.sfxGain = c.createGain(); this.filter = c.createBiquadFilter(); this.filter.type = 'lowpass'; this.filter.frequency.value = 2400;
      this.filter.connect(this.musicGain); this.musicGain.connect(c.destination); this.sfxGain.connect(c.destination);
      const len = c.sampleRate * 0.5, buf = c.createBuffer(1, len, c.sampleRate), d = buf.getChannelData(0); for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      this.noise = buf; this.refresh(); this.startMusic();
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
  }
  refresh() {                                                                                  // sync gains + UI buttons with the state
    for (const ch of ['music', 'sfx']) {
      const s = this.st[ch], btn = document.getElementById('mute-' + ch);
      if (btn) { btn.classList.toggle('off', s.mute || s.vol === 0); btn.textContent = (s.mute || s.vol === 0) ? '\u{1F507}' : ch === 'music' ? '\u{1F3B5}' : '\u{1F50A}'; }
      try { localStorage.setItem('island.' + ch, JSON.stringify(s)); } catch (e) { /* ignore */ }
    }
    if (!this.ctx) return; const t = this.ctx.currentTime;
    this.musicGain.gain.setTargetAtTime(this.st.music.mute ? 0 : this.st.music.vol * 0.3, t, 0.05);
    this.sfxGain.gain.setTargetAtTime(this.st.sfx.mute ? 0 : this.st.sfx.vol, t, 0.05);
  }
  setNight(n) { if (this.ctx) this.filter.frequency.setTargetAtTime(2600 - 1500 * n, this.ctx.currentTime, 0.5); }   // darker tone at night
  tone(midi, t, dur, type, peak, dest) {
    const c = this.ctx, o = c.createOscillator(), g = c.createGain(); o.type = type; o.frequency.value = 440 * Math.pow(2, (midi - 69) / 12);
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(peak, t + 0.03); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(dest); o.start(t); o.stop(t + dur + 0.05);
  }
  startMusic() {                                                                               // slow Am-F-C-G arpeggio + bass, scheduled ahead of time
    const c = this.ctx, chords = [[57, 60, 64], [53, 57, 60], [48, 52, 55], [55, 59, 62]], pat = [0, 1, 2, 1, 0, 2, 1, 2], eighth = 60 / 76 / 2;
    let step = 0, next = c.currentTime + 0.1;
    this.timer = setInterval(() => {
      while (next < c.currentTime + 0.6) {
        const bar = Math.floor(step / 8) % 4, ch = chords[bar], k = step % 8;
        this.tone(ch[pat[k]] + 12, next, eighth * 2.2, 'triangle', 0.5, this.filter);
        if (k === 0) { this.tone(ch[0] - 12, next, eighth * 7, 'sine', 0.7, this.filter); this.tone(ch[1], next, eighth * 7, 'sine', 0.25, this.filter); }
        next += eighth; step++;
      }
    }, 150);
  }
  burst(t, dur, freq, q, peak, type = 'bandpass') {                                            // filtered-noise helper for steps / creaks
    const c = this.ctx, s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain(); s.buffer = this.noise; f.type = type; f.frequency.value = freq; f.Q.value = q;
    g.gain.setValueAtTime(peak, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur); s.connect(f); f.connect(g); g.connect(this.sfxGain); s.start(t, Math.random() * 0.3); s.stop(t + dur + 0.02);
    return f;
  }
  sfx(name) {
    if (!this.ctx || this.st.sfx.mute) return; const c = this.ctx, t = c.currentTime;
    switch (name) {
      case 'step':   this.burst(t, 0.07, 380 + Math.random() * 220, 1.2, 0.35); break;
      case 'door':   { const f = this.burst(t, 0.45, 300, 4, 0.5); f.frequency.exponentialRampToValueAtTime(900, t + 0.4); this.tone(52, t, 0.25, 'sine', 0.6, this.sfxGain); break; }
      case 'sit':    this.tone(90, t, 0.14, 'sine', 0.7, this.sfxGain); this.burst(t, 0.1, 250, 1, 0.25); break;
      case 'portal': { const o = c.createOscillator(), g = c.createGain(); o.type = 'sawtooth'; o.frequency.setValueAtTime(120, t); o.frequency.exponentialRampToValueAtTime(900, t + 0.8);
                       g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.25, t + 0.2); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.9); o.connect(g); g.connect(this.sfxGain); o.start(t); o.stop(t + 1); break; }
      case 'click':  this.tone(880, t, 0.06, 'square', 0.15, this.sfxGain); break;
    }
  }
}

/* =============================== 5. BOOT ================================= */
class BootScene extends Phaser.Scene {
  constructor() { super('Boot'); }
  preload() {
    const L = this.load, bar = this.add.rectangle(C.VIEW_W / 2, C.VIEW_H / 2, 4, 10, 0xffe9a8).setOrigin(0, .5);
    this.add.text(C.VIEW_W / 2, C.VIEW_H / 2 - 30, 'Loading...', { fontFamily: '"Press Start 2P", monospace', fontSize: '14px', color: '#ffe9a8' }).setOrigin(.5);
    L.on('progress', p => bar.setSize(400 * p, 10).setX(C.VIEW_W / 2 - 200));
    this.missing = new Set(); L.on('loaderror', f => { this.missing.add(f.key); console.warn('Missing asset:', f.src); });
    L.image('atlas', 'environment-atlas-source.png'); L.image('actions', 'actions-source.png');            // benches + sit frames
    BUILDINGS.forEach(b => L.image(b.key, b.key + '-source.png'));
    const R = C.PLAYER_ROOT + 'Idle/';
    for (const d of C.DIRS) {                                                                                // 8 idle rotations + 6 walk frames per direction
      L.image('idle-' + d, R + 'rotations/' + d + '.png');
      for (let i = 0; i < C.WALK_FRAMES; i++) L.image(`walk-${d}-${i}`, `${R}animations/Walk/${d}/frame_${String(i).padStart(3, '0')}.png`);
    }
    L.image('mt', blobUrl(EMBED.mt)); L.image('nt', blobUrl(EMBED.nt)); L.image('lamp', blobUrl(EMBED.lamp));
    Object.entries(DOOR_ART).forEach(([k, d]) => L.image('door_' + k, blobUrl(d)));
    L.image('lamp-new', C.LAMP_FILE);                                                                        // new lamp post (optional file)
  }
  create() {
    const tx = this.textures, add = (t, n, r) => tx.get(t).add(n, 0, ...r);
    Object.entries(MT).forEach(([n, r]) => add('mt', n, r)); Object.entries(NT).forEach(([n, r]) => add('nt', n, r));
    C.BENCHES.forEach((r, i) => add('atlas', 'bn' + i, r)); C.ACT.forEach((r, i) => add('actions', 'a' + i, r));
    // ground anchors: bottom-most opaque pixel + horizontal centre of every character frame (so feet touch the ground exactly)
    const anchors = {};
    for (const d of C.DIRS) for (const k of [`idle-${d}`, ...Array.from({ length: C.WALK_FRAMES }, (_, i) => `walk-${d}-${i}`)]) if (tx.exists(k)) anchors[k] = this.measure(k);
    this.registry.set('anchors', anchors);
    this.registry.set('lamp', this.analyzeLamp(tx.exists('lamp-new') && !this.missing.has('lamp-new') ? 'lamp-new' : 'lamp'));
    this.scene.start('Game');
  }
  /** Reads the alpha channel of a texture: returns {top,bottom,left,right,w,h,imageData}. */
  pixels(key) {
    const img = this.textures.get(key).getSourceImage(), cv = document.createElement('canvas'); cv.width = img.width; cv.height = img.height;
    const g = cv.getContext('2d', { willReadFrequently: true }); g.drawImage(img, 0, 0); const d = g.getImageData(0, 0, cv.width, cv.height).data;
    let top = cv.height, bottom = 0, left = cv.width, right = 0;
    for (let y = 0; y < cv.height; y++) for (let x = 0; x < cv.width; x++) if (d[(y * cv.width + x) * 4 + 3] > 128) { if (y < top) top = y; if (y > bottom) bottom = y; if (x < left) left = x; if (x > right) right = x; }
    return { top, bottom, left, right, w: cv.width, h: cv.height, d };
  }
  measure(key) { const p = this.pixels(key); return [(p.left + p.right + 1) / 2 / p.w, (p.bottom + 1) / p.h]; }   // [origin x, origin y]
  /** Finds pole position, arm direction and lantern of any lamp art: pole = bottom rows, lantern = brightest warm pixels. */
  analyzeLamp(key) {
    const p = this.pixels(key); let sx = 0, n = 0, lx = 0, ly = 0, ln = 0;
    for (let y = p.bottom - 2; y <= p.bottom; y++) for (let x = 0; x < p.w; x++) if (p.d[(y * p.w + x) * 4 + 3] > 128) { sx += x; n++; }
    for (let y = p.top; y <= p.bottom; y++) for (let x = 0; x < p.w; x++) { const o = (y * p.w + x) * 4, r = p.d[o], g = p.d[o + 1], b = p.d[o + 2];
      if (p.d[o + 3] > 128 && r > 225 && g > 170 && b < 170) { lx += x; ly += y; ln++; } }
    const poleX = n ? sx / n : p.w / 2, lanternX = ln > 4 ? lx / ln : poleX, lanternY = ln > 4 ? ly / ln : p.top + (p.bottom - p.top) * .35;
    return { key, w: p.w, h: p.h, top: p.top, bottom: p.bottom, poleX, lanternX, lanternY, arm: Math.abs(lanternX - poleX) < 2 ? 0 : Math.sign(lanternX - poleX) };
  }
}

/* ============================ 6. SUN & SHADOWS ============================ */
/** Sun travels East -> West over the day half of the cycle; every registered object casts a flipped, squashed, rotated black copy of itself. */
class SunSystem {
  constructor(scene) { this.scene = scene; this.list = []; this.player = null; this.angle = 0; this.len = 1; this.alpha = 0; }
  /** Registers an object: texture/frame, base point (x,y), the object's own origin, scale and flip. */
  add(key, frame, x, y, ox, oy, sx, sy, flip = false, k = 1) {
    const img = this.scene.add.image(x, y, key, frame).setOrigin(ox, 1 - oy).setFlipY(true).setFlipX(flip).setTintFill(0x000000).setDepth(1.5);   // flipped: grows away from the base
    this.list.push({ img, sx, sy, k }); return img;
  }
  trackPlayer(sprite) { this.player = { sprite, img: this.scene.add.image(0, 0, sprite.texture.key).setFlipY(true).setTintFill(0x000000).setDepth(1.5) }; }
  update(phase) {
    const day = phase < 0.5, phi = Math.PI * Math.min(1, phase / 0.5), s = Math.sin(phi), S = C.SUN;
    this.alpha = day ? S.alpha * Math.min(1, s * 2.2) : 0;                                   // fades near sunrise/sunset, none at night
    this.len = S.minLen + (S.maxLen - S.minLen) * (1 - s);                                    // long at the horizon, short at noon
    this.angle = Phaser.Math.RadToDeg(Math.atan2(Math.cos(phi), S.southBias));               // morning: points west, noon: south, evening: points east
    for (const e of this.list) e.img.setAngle(this.angle).setScale(e.sx, e.sy * this.len * e.k).setAlpha(this.alpha).setVisible(this.alpha > .01);
    const p = this.player; if (!p) return;
    const sp = p.sprite; p.img.setTexture(sp.texture.key, sp.frame.name).setOrigin(sp.originX, 1 - sp.originY).setFlipX(sp.flipX).setPosition(sp.x, sp.y)
      .setAngle(this.angle).setScale(sp.scaleX, sp.scaleY * this.len).setAlpha(this.alpha).setVisible(this.alpha > .01);
  }
}

/* ========================= 7. NIGHT LIGHTING SYSTEM ======================= */
const NIGHT_KEYS = [[0, .3], [.06, 0], [.42, 0], [.52, .6], [.6, 1], [.9, 1], [1, .3]];   // cycle position -> darkness 0..1 (wraps seamlessly)
const nightAmount = t => { for (let i = 1; i < NIGHT_KEYS.length; i++) if (t <= NIGHT_KEYS[i][0]) { const a = NIGHT_KEYS[i - 1], b = NIGHT_KEYS[i]; return a[1] + (b[1] - a[1]) * (t - a[0]) / (b[0] - a[0]); } return 0; };

/** Dark navy RenderTexture over the whole view; radial ERASE cut-outs for the player and for every lamp that is switched on. */
class LightSystem {
  constructor(scene, lamps) {
    this.scene = scene; this.lamps = lamps; this.lampOn = 0;
    const grad = (key, R, stops) => { const t = scene.textures.createCanvas(key, 2 * R, 2 * R), g = t.context.createRadialGradient(R, R, 0, R, R, R);
      stops.forEach(([o, c]) => g.addColorStop(o, c)); t.context.fillStyle = g; t.context.fillRect(0, 0, 2 * R, 2 * R); t.refresh(); };
    grad('lampLight', C.LAMP_RADIUS, [[0, 'rgba(255,255,255,1)'], [.5, 'rgba(255,255,255,.85)'], [1, 'rgba(255,255,255,0)']]);
    grad('playerLight', C.PLAYER_LIGHT_RADIUS, [[0, 'rgba(255,255,255,.9)'], [.6, 'rgba(255,255,255,.5)'], [1, 'rgba(255,255,255,0)']]);
    grad('lampGlow', C.LAMP_RADIUS, [[0, 'rgba(255,196,90,.6)'], [.5, 'rgba(255,150,40,.22)'], [1, 'rgba(255,120,20,0)']]);
    this.dark = scene.add.renderTexture(0, 0, C.VIEW_W, C.VIEW_H).setOrigin(0).setScrollFactor(0).setDepth(2e5);
    this.glows = lamps.map(l => scene.add.image(l.lx, l.ly, 'lampGlow').setBlendMode(Phaser.BlendModes.ADD).setDepth(2e5 + 1).setAlpha(0));
  }
  update(night, dt, player) {
    const cam = this.scene.cameras.main, R = C.LAMP_RADIUS, PR = C.PLAYER_LIGHT_RADIUS;
    const target = night > 0.55 ? 1 : 0; this.lampOn += (target - this.lampOn) * Math.min(1, dt * 2.5);   // lamps switch on only in the Night phase
    this.dark.clear();
    if (night > .01) {
      this.dark.fill(C.NIGHT_COLOR, C.NIGHT_ALPHA * night);                                  // #05051a at ~0.88 alpha
      this.dark.erase('playerLight', player.x - cam.scrollX - PR, player.y - 36 - cam.scrollY - PR);   // ambient light around the player
      if (this.lampOn > .35) for (const l of this.lamps) {
        const sx = l.lx - cam.scrollX, sy = l.ly - cam.scrollY;
        if (sx > -R && sx < cam.width + R && sy > -R && sy < cam.height + R) this.dark.erase('lampLight', sx - R, sy - R);
      }
    }
    this.glows.forEach(g => g.setAlpha(this.lampOn));
  }
}

/* ============================== 8. GAME SCENE ============================= */
class GameScene extends Phaser.Scene {
  constructor() { super('Game'); }

  create() {
    this.audio = this.registry.get('audio'); this.anchors = this.registry.get('anchors'); this.lampInfo = this.registry.get('lamp');
    this.isl = new IslandMap(); this.solids = this.physics.add.staticGroup(); this.doors = this.physics.add.staticGroup();
    this.solidRects = []; this.occupied = []; this.benches = []; this.lamps = []; this.waterTiles = [];
    let seed = 12345; this.rnd = () => (seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296;
    this.sun = new SunSystem(this);
    this.buildGround(); this.buildWorld(); this.createPlayer();
    this.nav = new NavGrid(this.isl, this.solidRects);
    this.light = new LightSystem(this, this.lamps);
    this.physics.add.collider(this.feet, this.solids); this.physics.add.collider(this.feet, this.waterBlock); this.physics.add.collider(this.feet, this.lampGroup);
    this.physics.add.overlap(this.feet, this.doors, (f, z) => this.enterDoor(z.b));
    const cam = this.cameras.main; cam.setBounds(0, 0, MW * T, MH * T); cam.startFollow(this.player, true, .12, .12); cam.roundPixels = true;
    this.physics.world.setBounds(0, 0, MW * T, MH * T);
    this.K = this.input.keyboard.addKeys('W,A,S,D,E,UP,DOWN,LEFT,RIGHT');
    this.input.on('pointerdown', ptr => this.onPointer(ptr));                                 // mouse click or touch tap
    this.marker = this.add.circle(0, 0, 12).setStrokeStyle(3, 0xffffff).setDepth(9e4).setAlpha(0);
    this.state = 'walk'; this.face = 'south'; this.cool = 0; this.portal = false; this.route = null; this.pendingSit = null; this.stepT = 0; this.hudMin = -1;
    this.hud = document.getElementById('hud'); this.hint = document.getElementById('hint'); this.portalEl = document.getElementById('portal');
    addEventListener('keydown', e => { if (this.portal && ['Space', 'Escape', 'Enter'].includes(e.code)) this.closePortal(); });
    this.portalEl.addEventListener('pointerdown', () => { if (this.portal) this.closePortal(); });   // tap to leave the portal on touch screens
    this.time.addEvent({ delay: 650, loop: true, callback: () => { this.step = (this.step || 0) + 1; this.waterTiles.forEach(w => w.img.setFrame('w' + ((w.h + this.step) % 4))); } });   // ONLY water animates
  }

  /* ---------- ground: old grass + dirt, new water, cliffs with a smooth old-grass cap ---------- */
  buildGround() {
    const I = this.isl, mk = (f, x, y, w = T + 1, h = T + 1, k = 'mt') => this.add.image(x, y, k, f).setOrigin(0).setDisplaySize(w, h);
    const fr = this.add.graphics().setDepth(1); fr.fillStyle(0x4a9a2c);
    for (let j = 0; j < MH; j++) for (let i = 0; i < MW; i++) {
      const x = i * T, y = j * T, h = hs(i, j);
      if (I.ch(i, j) === '.') { this.waterTiles.push({ h, img: mk('w' + (h % 4), x, y, T + 1, T + 1, 'nt') }); continue; }
      if (I.type(i, j) === PATH) {
        mk('dirt', x, y);
        if (I.type(i, j - 1) !== PATH) fr.fillRect(x, y, T + 1, 4); if (I.type(i, j + 1) !== PATH) fr.fillRect(x, y + T - 3, T + 1, 4);
        if (I.type(i - 1, j) !== PATH) fr.fillRect(x, y, 4, T + 1); if (I.type(i + 1, j) !== PATH) fr.fillRect(x + T - 3, y, 4, T + 1);
      } else mk('g' + [0,1,5,6,0,1,5,6,2,3,4,7,8,9][h % 14], x, y);                         // original grass style
      if (I.ch(i, j - 1) === '.') mk('rimh', x, y - 3, T + 1, 7, 'nt').setDepth(3);
    }
    const M = I.cliffs, u = T / 64;
    const piece = (key, i, j, over = 0) => {                                                // top / side piece with the old grass painted over its grass band
      const r = NT[key], end = key[1], w = (/^T[LR]$/.test(key) ? Math.min(1, r[2] / 54) : 1) * T + 1, ph = r[3] * u, d = .6 + j * .001;
      const x = end === 'L' ? i * T - over : end === 'R' ? i * T + T - w + 1 + over : i * T, top = (j + 1) * T - ph;
      this.add.image(x, (j + 1) * T, 'nt', key).setOrigin(0, 1).setDisplaySize(w, ph).setDepth(d);
      this.add.image(x, top, 'mt', 'g' + (hs(i, j) % 10)).setOrigin(0).setDisplaySize(w, ph * C.CAP_FRAC).setDepth(d + .0005);   // grass stays smooth over the cliff edge
      fr.fillRect(x, top + ph * C.CAP_FRAC - 1, w, 3);
    };
    for (let j = 0; j < MH + 4; j++) for (let i = 0; i < MW; i++) {
      const f = M.face[j][i], b = M.base[j][i];
      if (f) this.add.image(i * T, j * T, 'nt', f).setOrigin(0).setDisplaySize(T + 1, (f[0] === 'C' ? 3 : 1) * T).setFlipX(f === 'CL').setDepth(.5);
      if (b) this.add.image(i * T, j * T, 'nt', b).setOrigin(0).setDisplaySize(T + 1, 2 * T).setDepth(.5);
      if (j < MH && M.top[j][i]) piece(M.top[j][i], i, j);
      if (j < MH && M.side[j][i]) piece('T' + M.side[j][i], i, j, 8);
    }
  }

  rect(group, x, y, w, h) { const z = this.add.zone(x + w / 2, y + h / 2, w, h); group.add(z); if (group === this.solids) this.solidRects.push([x, y, w, h]); return z; }

  /* ---------- buildings, fountain, signs, lamps, benches, scenery ---------- */
  buildWorld() {
    const I = this.isl, K = C.BUILD_W / 1374;
    this.waterBlock = this.physics.add.staticGroup(); this.lampGroup = this.physics.add.staticGroup();
    for (let j = 0; j < MH; j++) for (let i = 0; i < MW; i++) {                              // island rim (top-edge tiles) = solid
      if (I.type(i, j) !== RIM) continue; let n = 1; while (I.type(i + n, j) === RIM) n++;
      this.rect(this.solids, i * T, j * T, n * T, T); i += n - 1;
    }
    const near = (i, j) => { for (let a = -2; a <= 2; a++) for (let b = -2; b <= 2; b++) if (I.plat(i + a, j + b)) return true; return false; };
    for (let j = 0; j < MH; j++) for (let i = 0; i < MW; i++) {                              // water around the island = solid
      if (I.ch(i, j) !== '.' || !near(i, j)) continue; let n = 1; while (I.ch(i + n, j) === '.' && near(i + n, j)) n++;
      this.rect(this.waterBlock, i * T, j * T, n * T, T); i += n - 1;
    }
    // buildings (door overlays carry doorAngle / doorOffsetX / doorOffsetY)
    for (const b of BUILDINGS) {
      const tex = this.textures.get(b.key).getSourceImage(), bw = C.BUILD_W, bh = tex.height * K, px = b.ax * T, py = b.ay * T, bx = px - b.dx * bw, by = py - b.dy * bh;
      Object.assign(b, { px, py, bx, by, bw, bh });
      this.add.image(bx, by, b.key).setOrigin(0).setDisplaySize(bw, bh).setDepth(py);
      this.sun.add(b.key, undefined, bx + bw / 2, by + bh * .97, .5, 1, bw / tex.width, bh / tex.height, false, .5);
      const dr = DOOR_RECTS[b.key]; b.openStyle = b.key === 'home'; b.open = false;           // HOME art is closed -> overlay = open door; others' art is open -> overlay = closed door
      b.art = this.add.image(bx + b.doorOffsetX, by + b.doorOffsetY, 'door_' + b.key).setOrigin(.5).setDisplaySize(dr[2] * K, dr[3] * K).setAngle(b.doorAngle).setDepth(py + .01).setVisible(!b.openStyle);
      const top = by + .35 * bh; this.rect(this.solids, bx + .04 * bw, top, .92 * bw, py - 6 - top);
      this.rect(this.doors, px - 32, py - 4, 64, 26).b = b;
      const s = b.sign, fs = Math.max(6, Math.min(14, Math.floor(s.w * K * .88 / b.n.length)));
      this.add.text(bx + s.x * K, by + s.y * K, b.n, { fontFamily: '"Press Start 2P", monospace', fontSize: fs + 'px', color: '#ffe9a8', stroke: '#2a1408', strokeThickness: fs > 9 ? 3 : 2 })
        .setOrigin(.5).setAngle(s.a).setDepth(py + .5);
    }
    // fountain: 3x3-tile solid base
    const fy = CY * T + 66;
    this.add.image(CX * T, fy, 'mt', 'fountain').setOrigin(.5, 1).setScale(C.FOUNTAIN_SCALE).setDepth(fy);
    this.sun.add('mt', 'fountain', CX * T, fy, .5, 1, C.FOUNTAIN_SCALE, C.FOUNTAIN_SCALE);
    this.rect(this.solids, CX * T - 1.5 * T, fy - 3 * T, 3 * T, 3 * T);
    // benches
    [[9, 25], [9, 155], [9, 205], [9, 335]].forEach(([r, a], i) => {
      const x = (CX + r * Math.cos(a * Math.PI / 180)) * T, y = (CY + r * Math.sin(a * Math.PI / 180)) * T, b = { x, y };
      this.add.image(x, y, 'atlas', 'bn' + (i % 2)).setOrigin(.5, 1).setScale(C.BENCH_SCALE).setDepth(y);
      this.sun.add('atlas', 'bn' + (i % 2), x, y, .5, 1, C.BENCH_SCALE, C.BENCH_SCALE); this.benches.push(b); this.occupied.push({ x, y, r: 70 });
    });
    this.buildSigns(); this.buildLamps();
    // scenery on flat grass only: trees (solid trunks), rocks (solid, static), bushes + tufts (decor)
    this.scatter(C.TREE_COUNT, { gap: 56 }, (X, Y) => { this.addDecor('mt', 'tr' + ((this.rnd() * 10) | 0), X, Y, C.TREE_SCALE, true); this.rect(this.solids, X - 9, Y - 11, 18, 11); });
    this.scatter(C.ROCK_COUNT, { gap: 90 }, (X, Y) => {                                      // rocks are plain static images: they never animate
      const n = (this.rnd() * 6) | 0, big = n >= 4; this.addDecor('nt', 'rk' + n, X, Y, big ? .5 : 1.1, true);
      this.rect(this.solids, X - (big ? 20 : 14), Y - (big ? 14 : 10), big ? 40 : 28, big ? 14 : 10);
    });
    this.scatter(C.BUSH_COUNT, { gap: 60, edge: 2 }, (X, Y) => this.addDecor('mt', 'bs' + ((this.rnd() * 5) | 0), X, Y, 1.2, true));
    this.scatter(C.TUFT_COUNT, { gap: 30, edge: 2, path: 1.3 }, (X, Y) => this.addDecor('mt', 'tf' + ((this.rnd() * 8) | 0), X, Y, 1.1, false));
  }
  addDecor(tex, frame, X, Y, sc, shadow) {
    this.add.image(X, Y, tex, frame).setOrigin(.5, 1).setScale(sc).setDepth(Y);
    if (shadow) this.sun.add(tex, frame, X, Y, .5, 1, sc, sc);
  }
  /** Random placement on valid flat ground: grass only, never cliff / cliff edge / rim / water, clear of paths, buildings and other objects. */
  scatter(count, o, make) {
    const I = this.isl, cl = I.cliffs, edge = o.edge ?? 3, pathMin = o.path ?? 1.9; let placed = 0;
    for (let n = 0; n < 8000 && placed < count; n++) {
      const x = this.rnd() * MW, y = this.rnd() * MH, i = x | 0, j = y | 0, X = x * T, Y = y * T;
      if (I.type(i, j) !== GRASS || cl.top[j][i] || cl.face[j][i] || cl.side[j][i]) continue;
      if ([[edge, 0], [-edge, 0], [0, edge], [0, -edge], [2, 2], [-2, -2], [2, -2], [-2, 2]].some(([a, b]) => { const k = I.type((x + a) | 0, (y + b) | 0); return k !== GRASS && k !== PATH; })) continue;
      if (I.pathDist(x, y) < pathMin || Math.hypot(x - CX, y - CY) < 7.5) continue;
      if (BUILDINGS.some(b => X > b.bx - 40 && X < b.bx + b.bw + 40 && Y > b.by - 40 && Y < b.py + 90)) continue;
      if (this.occupied.some(q => Math.hypot(q.x - X, q.y - Y) < Math.max(q.r, o.gap))) continue;
      this.occupied.push({ x: X, y: Y, r: o.gap }); make(X, Y); placed++;
    }
  }

  /** Signposts at the junction of the inner ring and each spoke; the arrow points toward the building. */
  buildSigns() {
    const SDIR = { '-4':'W', '-3':'NW', '-2':'N', '-1':'NE', '0':'E', '1':'SE', '2':'S', '3':'SW', '4':'W' };
    for (const b of BUILDINGS) {
      const u = [(b.P[0] - CX) / RO, (b.P[1] - CY) / RO], n = [-u[1], u[0]];
      const sx = (b.Q[0] + C.SIGN_OFF.r * u[0] + C.SIGN_OFF.t * n[0]) * T, sy = (b.Q[1] + C.SIGN_OFF.r * u[1] + C.SIGN_OFF.t * n[1]) * T;
      const ang = Math.atan2(b.ay * T - sy, b.ax * T - sx) * 180 / Math.PI, d = C.SIGN_FRAMES[SDIR[Math.round(ang / 45)]];
      this.createSignpost(sx, sy, d.f, b.n, !!d.flip); this.occupied.push({ x: sx, y: sy, r: 80 });
    }
  }
  createSignpost(x, y, frame, textLabel, flip = false) {
    const r = MT[frame], b = C.SIGN_BOARD[frame], sc = C.SIGN_SCALE, dir = flip ? -1 : 1;
    const post = this.add.image(x, y, 'mt', frame).setOrigin(.5, 1).setScale(sc).setFlipX(flip).setDepth(y);
    this.sun.add('mt', frame, x, y, .5, 1, sc, sc, flip);
    const fs = Math.max(6, Math.min(10, Math.floor(b.w * sc * .9 / textLabel.length)));
    this.add.text(x + dir * (b.x - r[2] / 2) * sc, y - (r[3] - b.y) * sc, textLabel, { fontFamily: '"Press Start 2P", monospace', fontSize: fs + 'px', color: '#2b1405' })
      .setOrigin(.5).setAngle(b.a * dir).setDepth(y + .1);                                    // text anchored to the sign's own coordinates, above it
    this.rect(this.solids, x - 6, y - 6, 12, 6); return post;
  }

  /** Lamp posts outside every building (beside its walls) + 4 by the fountain. 3 tiles tall, base-only collision, arm over the path, top layer above the player. */
  buildLamps() {
    const I = this.isl, A = this.lampInfo, visH = A.bottom - A.top + 1, LS = C.LAMP_TILES * T / visH, LW = A.w * LS, LH = A.h * LS;
    const feetFrac = (A.bottom + 1) / A.h, baseSrc = T / LS, y0 = A.bottom + 1 - baseSrc, BWt = C.BUILD_W / T, spots = [];
    for (const b of BUILDINGS) for (const side of [-1, 1]) {                                 // outside the building: beside its footprint, on grass
      for (let off = 1.2; off <= 3.2; off += .5) {
        const x = side < 0 ? b.ax - b.dx * BWt - off : b.ax + (1 - b.dx) * BWt + off, y = b.ay + .8;
        if (I.type(x | 0, y | 0) === GRASS && I.type((x + side * .6) | 0, y | 0) === GRASS) { spots.push([x, y]); break; }
      }
    }
    [20, 160, 200, 340].forEach(a => spots.push([CX + 6.3 * Math.cos(a * Math.PI / 180), CY + 6.3 * Math.sin(a * Math.PI / 180)]));
    for (const [x, y] of spots) {
      const X = x * T, Y = y * T, pv = I.nearestPath(x, y), flip = A.arm !== 0 && (pv[1] * A.arm) < 0;   // arm + lantern point toward the dirt path
      const ox = flip ? 1 - A.poleX / A.w : A.poleX / A.w;
      const base = this.lampGroup.create(X, Y, A.key).setOrigin(ox, feetFrac).setScale(LS).setFlipX(flip).setDepth(Y).setCrop(0, y0, A.w, A.h - y0);   // bottom tile: y-sorted like the ground
      base.refreshBody(); base.body.setSize(C.LAMP_BASE_W, T, false); base.body.setOffset(ox * LW - C.LAMP_BASE_W / 2, feetFrac * LH - T);          // collision = post base only
      this.add.image(X, Y, A.key).setOrigin(ox, feetFrac).setScale(LS).setFlipX(flip).setDepth(6e4 + Y).setCrop(0, 0, A.w, y0);                   // arm + lantern always over the character
      this.sun.add(A.key, undefined, X, Y, ox, feetFrac, LS, LS, flip);
      this.solidRects.push([X - C.LAMP_BASE_W / 2, Y - T, C.LAMP_BASE_W, T]); this.occupied.push({ x: X, y: Y, r: 90 });
      const lfx = flip ? 1 - A.lanternX / A.w : A.lanternX / A.w;
      this.lamps.push({ x: X, y: Y, lx: X + (lfx - ox) * LW, ly: Y - (feetFrac - A.lanternY / A.h) * LH });   // light source = the lantern
    }
  }

  /* ---------- player: bottom-anchored sprite follows an invisible feet body ---------- */
  createPlayer() {
    const an = this.anims;
    this.player = this.add.sprite(0, 0, 'idle-south').setScale(C.PLAYER_SCALE);
    this.feet = this.add.zone(CX * T, (CY + RI) * T, C.FEET_W, C.FEET_H); this.physics.add.existing(this.feet); this.feet.body.setCollideWorldBounds(true);
    for (const d of C.DIRS) an.create({ key: 'walk-' + d, frames: Array.from({ length: C.WALK_FRAMES }, (_, i) => ({ key: `walk-${d}-${i}` })), frameRate: C.WALK_FPS, repeat: -1 });
    const af = a => a.map(i => ({ key: 'actions', frame: 'a' + i }));
    an.create({ key: 'sit-down', frames: af(C.SIT_IN), frameRate: C.SIT_FPS });
    an.create({ key: 'stand-up', frames: af([...C.SIT_IN].reverse()), frameRate: C.SIT_FPS });
    an.create({ key: 'sit-loop', frames: af(C.SIT_LOOP), frameRate: 3, repeat: -1 });
    this.sun.trackPlayer(this.player); this.anchorPlayer();
  }
  /** Re-anchors the sprite on the exact feet pixel of whichever frame is showing, so it never floats above or sinks below the ground. */
  anchorPlayer() { const a = this.anchors[this.player.texture.key]; if (a) this.player.setOrigin(a[0], a[1]); else this.player.setOrigin(.5, 1); }
  nearBench() { const f = this.feet; let best = null, bd = C.SIT_RANGE; for (const b of this.benches) { const d = Math.hypot(f.x - b.x, f.y - b.y); if (d < bd) { bd = d; best = b; } } return best; }
  sit(b) {
    const p = this.player, f = this.feet, sx = b.x, sy = b.y + C.SEAT_DY;
    this.state = 'sitting'; this.bench = b; this.route = null; this.pendingSit = null; this.audio.sfx('sit');
    f.body.setVelocity(0); f.body.reset(sx, sy - C.FEET_H / 2); f.body.enable = false;        // snap the physics body to the seat, then freeze it
    p.setPosition(sx, sy).setOrigin(.5, 1).setScale(C.ACTION_SCALE).play('sit-down');
    p.once('animationcomplete-sit-down', () => { if (this.state === 'sitting') { this.state = 'seated'; p.play('sit-loop'); } });
  }
  stand() {
    const p = this.player; this.state = 'standing'; p.play('stand-up');
    p.once('animationcomplete-stand-up', () => { this.feet.body.enable = true; this.feet.body.reset(p.x, p.y + 30 - C.FEET_H / 2); this.face = 'south'; this.state = 'walk'; });
  }

  /* ---------- click / tap to move (validated against the island) ---------- */
  onPointer(ptr) {
    if (this.portal) return;
    if (this.state === 'seated') { this.stand(); return; }
    if (this.state !== 'walk') return;
    const w = this.cameras.main.getWorldPoint(ptr.x, ptr.y);
    const bench = this.benches.find(b => Math.hypot(b.x - w.x, b.y - w.y) < 60);             // tapping a bench = walk there and sit
    const tx = bench ? bench.x : w.x, ty = bench ? bench.y + 36 : w.y;
    const route = this.nav.path(this.feet.x, this.feet.y, tx, ty);                            // goal is clamped to walkable tiles; null if unreachable
    if (!route || !route.length) return;
    this.route = route; this.pendingSit = bench || null;
    const g = route[route.length - 1]; this.marker.setPosition(g.x, g.y).setAlpha(1); this.tweens.killTweensOf(this.marker); this.tweens.add({ targets: this.marker, alpha: 0, duration: 700 });
  }
  /** Resolves keyboard + route into one movement vector. Keyboard always wins; routes are followed waypoint by waypoint. */
  readMove(dt) {
    const K = this.K;
    let vx = (K.D.isDown || K.RIGHT.isDown) - (K.A.isDown || K.LEFT.isDown), vy = (K.S.isDown || K.DOWN.isDown) - (K.W.isDown || K.UP.isDown);
    if (vx || vy) { this.route = null; this.pendingSit = null; return [vx, vy]; }
    if (!this.route) return [0, 0];
    const f = this.feet, wp = this.route[0], dx = wp.x - f.x, dy = wp.y - f.y, d = Math.hypot(dx, dy);
    this.stuck = (this.stuck || 0) + (this.lastD !== undefined && Math.abs(this.lastD - d) < .15 * C.SPEED * dt ? dt : -this.stuck); this.lastD = d;   // no progress for 0.6s -> give up (blocked)
    if (this.stuck > .6) { this.route = null; this.stuck = 0; return [0, 0]; }
    if (d < 6) { this.route.shift(); this.lastD = undefined; if (!this.route.length) { this.route = null; } return [0, 0]; }
    return [dx / d, dy / d];
  }
  /** Snaps a movement vector to the nearest of the 8 facings (diagonals win when both axes are used). */
  facing(vx, vy) {
    const a = Math.atan2(vy, vx) * 180 / Math.PI, names = ['east', 'south-east', 'south', 'south-west', 'west', 'north-west', 'north', 'north-east'];
    return names[((Math.round(a / 45) % 8) + 8) % 8];
  }

  /* ---------- portals / doors ---------- */
  enterDoor(b) {
    if (this.portal || this.cool > 0 || this.state !== 'walk') return;
    this.portal = true; this.door = b; this.route = null; this.feet.body.setVelocity(0); this.player.anims.stop(); this.audio.sfx('portal');
    this.portalEl.querySelector('h1').textContent = 'Entering ' + b.n + '...'; this.portalEl.classList.add('on'); console.log('[PORTAL] Entered building: ' + b.n);
  }
  closePortal() { this.portal = false; this.cool = 1.2; this.portalEl.classList.remove('on'); this.feet.body.reset(this.door.px, this.door.py + 60); }
  updateDoors() {                                                                             // doors start CLOSED, open while the player is near the entrance
    const f = this.feet;
    for (const b of BUILDINGS) {
      const near = Math.hypot(f.x - b.px, f.y - (b.py + 6)) < (b.open ? C.DOOR_CLOSE : C.DOOR_OPEN);
      if (near !== b.open) { b.open = near; b.art.setVisible(b.openStyle ? near : !near); this.audio.sfx('door'); }
    }
  }

  /* ---------- main loop ---------- */
  update(time, delta) {
    const dt = delta / 1000, p = this.player, f = this.feet;
    this.cool = Math.max(0, this.cool - dt);
    const phase = ((time / 1000 / C.DAY_SECONDS) + C.START_TIME) % 1, night = nightAmount(phase), hr = (phase * 24 + 6) % 24;
    const minute = Math.floor(hr * 60);
    if (minute !== this.hudMin) { this.hudMin = minute; this.hud.innerHTML = `WASD / Arrows or click / tap to move &nbsp;·&nbsp; E: sit &nbsp;·&nbsp; Walk into a door to enter<br>Time ${String(hr | 0).padStart(2, '0')}:${String((hr % 1) * 60 | 0).padStart(2, '0')}`; }
    this.sun.update(phase); this.light.update(night, dt, p); this.audio.setNight(night);
    if (this.portal) { f.body.setVelocity(0); return; }
    if (this.state === 'walk') {
      const [vx, vy] = this.readMove(dt), moving = !!(vx || vy);
      const len = Math.hypot(vx, vy) || 1, speed = this.route && this.route.length === 1 ? Math.min(C.SPEED, Math.hypot(this.route[0].x - f.x, this.route[0].y - f.y) * 8 + 40) : C.SPEED;   // ease into the last waypoint
      f.body.setVelocity(vx / len * speed, vy / len * speed);                                // normalised: diagonals are not faster
      if (moving) {
        this.face = (this.K.D.isDown || this.K.A.isDown || this.K.W.isDown || this.K.S.isDown || this.K.UP.isDown || this.K.DOWN.isDown || this.K.LEFT.isDown || this.K.RIGHT.isDown)
          ? DIRN_KEYS[Math.sign(vx) + ',' + Math.sign(vy)] : this.facing(vx, vy);            // keyboard: two keys held = diagonal wins; taps: 8-way snap of the heading
        p.setScale(C.PLAYER_SCALE).anims.play('walk-' + this.face, true);
        this.stepT -= dt; if (this.stepT <= 0) { this.audio.sfx('step'); this.stepT = .34; }
      } else { p.anims.stop(); p.setTexture('idle-' + this.face).setScale(C.PLAYER_SCALE); this.stepT = 0; }
      this.anchorPlayer();
      p.setPosition(f.x, f.y + C.FEET_H / 2); p.setDepth(p.y);                               // depth = feet y: behind objects above, in front of objects below
      if (this.pendingSit && !this.route) { const nb = this.nearBench(); if (nb === this.pendingSit) this.sit(nb); this.pendingSit = null; }
      if (Phaser.Input.Keyboard.JustDown(this.K.E)) { const bn = this.nearBench(); if (bn) this.sit(bn); }   // after the follow-position, so the seat snap is not overwritten
    } else {
      if (this.state === 'seated' && (Phaser.Input.Keyboard.JustDown(this.K.E) || this.readMove(dt).some(v => v))) this.stand();
      if (this.state !== 'standing') p.setPosition(this.bench.x, this.bench.y + C.SEAT_DY);   // stay pinned to the seat
      p.setDepth(this.bench.y + 1);
    }
    this.updateDoors();
    const showHint = (this.state === 'walk' && this.nearBench()) || this.state === 'seated';
    this.hint.style.opacity = showHint ? 1 : 0; this.hint.textContent = this.state === 'seated' ? 'Press E (or tap) to stand up' : 'Press E (or tap the bench) to sit';
  }
}
const DIRN_KEYS = { '0,1':'south', '1,1':'south-east', '1,0':'east', '1,-1':'north-east', '0,-1':'north', '-1,-1':'north-west', '-1,0':'west', '-1,1':'south-west', '0,0':'south' };

/* ============================== 9. BOOTSTRAP ============================== */
function startGame() {
  ['gesturestart', 'gesturechange', 'gestureend'].forEach(e => document.addEventListener(e, ev => ev.preventDefault()));   // iOS pinch-zoom guard
  document.addEventListener('contextmenu', e => e.preventDefault());
  const audio = new AudioSystem();
  const boot = () => {
    const game = new Phaser.Game({
      type: Phaser.AUTO, parent: 'game', backgroundColor: '#1d6fb8', pixelArt: true, roundPixels: true, audio: { noAudio: true },   // sound is handled by AudioSystem
      scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH, width: C.VIEW_W, height: C.VIEW_H },                    // responsive: phones, tablets, desktops
      physics: { default: 'arcade', arcade: { debug: false } }, input: { touch: true }, scene: [BootScene, GameScene]
    });
    game.registry.set('audio', audio);
  };
  Promise.race([document.fonts.load('14px "Press Start 2P"'), new Promise(r => setTimeout(r, 1500))]).catch(() => {}).then(boot);   // wait for the pixel font
}
if (typeof window !== 'undefined' && typeof Phaser !== 'undefined' && !(typeof module !== 'undefined' && module.exports)) window.addEventListener('DOMContentLoaded', startGame);
if (typeof module !== 'undefined' && module.exports) module.exports = { IslandMap, NavGrid, BUILDINGS, nightAmount, C };
